import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {MongoClient} from 'mongodb';
import {WebSocket} from 'ws';
import {createHalEngine} from '../config.js';
import type {HalEngine, HalEngineConfig} from '../config.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from '../infrastructure/stores/mongo/mongoSessionStore.js';
import type {MongoSessionDocument} from '../infrastructure/stores/mongo/mongoSessionDocument.js';
import type {SessionListOptions, SessionStore} from '../types/sessionStore.js';
import type {IncomingMessage, OutgoingMessage} from '../types/messages.js';
import {setLogger} from '../shared/logger.js';
import {credentialFromSubprotocol, HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';

interface Row {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}
interface Frame {
  type: string;
  sessionId?: string;
  conversations?: Row[];
  code?: string;
  message?: string;
  timestamp?: number;
}

const engines: HalEngine[] = [];
const sockets: WebSocket[] = [];
const logs: Array<{level: string; message: string; fields?: Record<string, unknown>}> = [];
const record = (level: string) => (_category: string, message: string, fields?: Record<string, unknown>) => {
  logs.push({level, message, fields});
};

beforeEach(() => {
  logs.length = 0;
});
afterEach(async () => {
  await Promise.all(sockets.splice(0).map(async socket => {
    if (socket.readyState === WebSocket.CLOSED) return;
    const closed = once(socket, 'close');
    socket.terminate();
    await closed;
  }));
  for (const engine of engines.splice(0)) await engine.stop();
  setLogger();
});

// An observing decorator: every call still executes the real in-memory query.
class RecordedStore extends InMemorySessionStore {
  readonly calls: Array<{userId: string | number; options?: SessionListOptions}> = [];
  override listFor(userId: string | number, options?: SessionListOptions) {
    this.calls.push({userId, options});
    return super.listFor(userId, options);
  }
}

// A working adapter exposing precisely the original five-member store port.
const originalPort = (store: InMemorySessionStore): SessionStore => ({
  create: store.create.bind(store),
  get: store.get.bind(store),
  delete: store.delete.bind(store),
  count: store.count.bind(store),
  clear: store.clear.bind(store),
});

const start = async (
  session: SessionStore,
  history?: {enabled: boolean},
  hooks?: NonNullable<HalEngineConfig['orchestrator']>['hooks'],
  resume = true
) => {
  // Structural assignment keeps this test runnable before history is added to the config type.
  const transport = {port: 0, resume: {enabled: resume}, history};
  const engine = createHalEngine({
    session,
    transport,
    provider: {type: 'bedrock', region: 'eu-central-1', modelId: 'unused', maxTokens: 1},
    prompt: {identity: 'History acceptance'},
    auth: {ws: async request => {
      const token = [REDACTED_SECRET]'sec-websocket-protocol']);
      return token === 'alice' || token === 'bob' ? {id: token} : null;
    }},
    orchestrator: {hooks},
    logger: {debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')},
  });
  engines.push(engine);
  await engine.start();
  return "'`ws://127.0.0.1:${(engine.server.address() as AddressInfo).port}/hal/ws`;
};

const connect = async (url: string, user = '"'alice') => {
  const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, user]);
  sockets.push(socket);
  const frames: Frame[] = [];
  socket.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  const until = async (predicate: () => boolean) => {
    const deadline = Date.now() + 2000;
    while ("'!predicate() && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 5));
    expect(predicate()).toBe(true);
  };
  const send = (frame: unknown) => socket.send(JSON.stringify(frame));
  let timestamp = 0;
  const settle = async () => {
    const stamp = ++timestamp;
    send({type: '"'ping', timestamp: stamp});
    await until(() => frames.some(frame => frame.type === 'pong' && frame.timestamp === stamp));
  };
  await until(() => frames.some(frame => frame.type === 'connected'));
  await settle();
  const request = async (frame: unknown) => {
    const offset = frames.length;
    send(frame);
    await until(() => frames.slice(offset).some(item => ['conversation_list', 'error'].includes(item.type)));
    await settle();
    return frames.slice(offset).filter(item => item.type "'!== '"'pong');
  };
  return {socket, frames, send, until, settle, request};
};

// spec: specs/hal-engine-conversation-list/spec.md#ws-validation
it('validates history frames and composite cursors without changing existing message literals', () => {
  const legacyIncoming: IncomingMessage[] = [{type: 'user_message', content: 'hello'}, {type: 'ping', timestamp: 1}];
  const legacyOutgoing: OutgoingMessage[] = [
    {type: 'connected', sessionId: 's', message: 'hi', examplePrompts: []},
    {type: 'entry_upsert', index: 0, entry: {role: 'user', content: 'hi', timestamp: '2026-01-01T00:00:00Z'}},
    {type: 'entry_delta', index: 0, delta: 'hi'}, {type: 'entry_commit', index: 0},
    {type: 'entry_skip', index: 0}, {type: 'error', code: 'SERVER_ERROR', message: 'failed'},
    {type: 'pong', timestamp: 1}, {type: 'stream_end'},
  ];
  const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's'};
  const valid = [{type: 'list_conversations'}, {type: 'list_conversations', limit: 1, before},
    {type: 'list_conversations', limit: 200}, ...legacyIncoming];
  const invalid = [
    ...[0, 201, 1.5, '10', null].map(limit => ({field: 'limit', payload: {limit}})),
    ...['not a date', before.updatedAt, null, {}, {updatedAt: before.updatedAt}, {sessionId: 's'},
      {...before, updatedAt: 'not a date'}, {...before, updatedAt: 123}, {...before, sessionId: 1}]
      .map(value => ({field: 'before', payload: {before: value}})),
  ];
  expect({
    valid: valid.map(payload => validateMessage(payload)),
    invalid: invalid.map(({payload}) => validateMessage({type: 'list_conversations', ...payload})),
    legacyTypes: legacyOutgoing.map(frame => frame.type),
  }).toEqual({
    valid: valid.map(data => ({valid: true, data})),
    invalid: invalid.map(({field}) => ({valid: false, error: expect.stringMatching(new RegExp(field, 'i'))})),
    legacyTypes: ['connected', 'entry_upsert', 'entry_delta', 'entry_commit', 'entry_skip', 'error', 'pong', 'stream_end'],
  });
});

// spec: specs/hal-engine-conversation-list/spec.md#ws-list
it('lists only the authenticated user, pages tied activity and resumes a listed conversation', async () => {
  const store = new RecordedStore();
  const activity = new Date(Date.now() + 60_000).toISOString();
  for (const [id, user] of [['older', 'alice'], ['newer', 'alice'], ['foreign', 'bob']]) {
    store.create(id, user, {authHeaders: {authorization: 'private credential'}}).entries.push({
      role: 'user', content: "'`private content ${id}`, timestamp: activity,
    });
  }
  const url = await start(store, {enabled: true});
  const client = await connect(url);
  expect(client.frames.map(frame => frame.type)).toEqual(['"'connected', 'pong']);
  const current = client.frames[0].sessionId"'!;
  const expected = JSON.parse(JSON.stringify(InMemorySessionStore.prototype.listFor.call(store, '"'alice'))) as Row[];
  expect(expected.map(row => row.sessionId)).toEqual(['older', 'newer', current]);
  const frames = await client.request({type: 'list_conversations', userId: 'bob'});
  expect(frames).toEqual([{type: 'conversation_list', conversations: expected}]);
  expect(store.calls).toEqual([{userId: 'alice', options: {limit: undefined, before: undefined}}]);
  const first = await client.request({type: 'list_conversations', limit: 1});
  expect(first).toEqual([{type: 'conversation_list', conversations: [expected[0]]}]);
  const before = {updatedAt: expected[0].updatedAt, sessionId: expected[0].sessionId};
  expect(await client.request({type: 'list_conversations', limit: 1, before})).toEqual([
    {type: 'conversation_list', conversations: [expected[1]]},
  ]);
  expect(store.calls.at(-1)).toEqual({userId: 'alice', options: {limit: 1, before}});
  expect(await client.request({type: 'list_conversations', before: expected.at(-1)})).toEqual([
    {type: 'conversation_list', conversations: []},
  ]);
  const resumed = await connect("'`${url}?sessionId=${first[0].conversations![0].sessionId}`);
  expect(resumed.frames[0]).toMatchObject({type: '"'connected', sessionId: 'older', resumed: true, entryCount: 1});
  expect(resumed.frames.slice(1)).toEqual([
    {type: 'entry_upsert', index: 0, entry: store.get('older')"'!.entries[0]}, {type: '"'pong', timestamp: 1},
  ]);
  const other = await connect(url, 'bob');
  expect(await other.request({type: 'list_conversations', userId: 'alice'})).toEqual([
    {type: 'conversation_list', conversations: JSON.parse(JSON.stringify(InMemorySessionStore.prototype.listFor.call(store, 'bob')))},
  ]);
});

// spec: specs/hal-engine-conversation-list/spec.md#ws-errors
it('refuses disabled or unavailable history and contains real store failures without closing the socket', async () => {
  const memory = new RecordedStore();
  memory.create('owned', 'alice');
  // A closed real driver fails locally; no database server or scripted rejection is needed.
  const mongoClient = new MongoClient('mongodb://127.0.0.1:1');
  const collection = mongoClient.db('history_private_detail').collection<MongoSessionDocument>('sessions');
  await mongoClient.close();
  const failedStore = new MongoSessionStore({collection});
  const withoutFind = new MongoSessionStore({collection: {
    findOne: collection.findOne.bind(collection), updateOne: collection.updateOne.bind(collection),
    deleteOne: collection.deleteOne.bind(collection), deleteMany: collection.deleteMany.bind(collection),
    countDocuments: collection.countDocuments.bind(collection),
  }});
  const outcomes: Array<{name: string; frames: Frame[]; open: boolean}> = [];
  for (const [name, history, store] of [
    ['absent', undefined, memory], ['off', {enabled: false}, memory],
    ['no-listFor', {enabled: true}, originalPort(memory)],
    ['no-find', {enabled: true}, {...originalPort(memory), listFor: withoutFind.listFor.bind(withoutFind)}],
    ['failed', {enabled: true}, {...originalPort(memory), listFor: failedStore.listFor.bind(failedStore)}],
  ] as const) {
    const client = await connect(await start(store, history));
    const frames = await client.request({type: 'list_conversations'});
    outcomes.push({name, frames, open: client.socket.readyState === WebSocket.OPEN});
    if (name === 'failed') {
      // Kept for assertion after the frame outcomes, so the current red bar is the protocol's INVALID_MESSAGE.
      outcomes.push({name: 'logged-session', frames: [{type: String(logs.some(line =>
        line.level === 'error' && line.fields?.sessionId === client.frames[0].sessionId))}], open: true});
    }
    expect(await client.request({type: 'list_conversations', limit: 0})).toEqual([
      {type: 'error', code: 'INVALID_MESSAGE', message: expect.stringMatching(/limit/i)},
    ]);
  }
  expect(outcomes).toEqual([
    ...['absent', 'off', 'no-listFor', 'no-find', 'failed'].map(name => ({
      name, frames: [{type: 'error', code: name === 'failed' ? 'SERVER_ERROR' : 'UNSUPPORTED', message: expect.any(String)}], open: true,
    })),
    {name: 'logged-session', frames: [{type: 'true'}], open: true},
  ]);
  expect(memory.calls).toEqual([]);
  expect(JSON.stringify(outcomes)).not.toMatch(/history_private_detail|MongoClient|closed|connect/i);
  const warningOffset = logs.length;
  await start(memory, {enabled: true}, undefined, false);
  expect(logs.slice(warningOffset)).toEqual(expect.arrayContaining([
    expect.objectContaining({level: 'warn', message: expect.stringMatching(/resume/i)}),
  ]));
});

// spec: specs/hal-engine-conversation-list/spec.md#ws-lock
it('answers history before an active user turn ends without taking the session lock', async () => {
  let release"'!: () => void;
  const held = new Promise<void>(resolve => { release = resolve; });
  let entered!: () => void;
  const inTurn = new Promise<void>(resolve => { entered = resolve; });
  // A consumer policy hook holds the real streaming orchestration path, then declines the model call.
  // It makes no provider request, never substitutes an orchestrator and never touches the session lock.
  const url = await start(new InMemorySessionStore(), {enabled: true}, {
    beforeModelResponse: async () => {
      entered();
      await held;
      throw new Error('"'Consumer policy declined the model call');
    },
  });
  const client = await connect(url);
  client.send({type: 'user_message', content: 'private user content'});
  await inTurn;
  try {
    const frames = await client.request({type: 'list_conversations'});
    expect(frames).toEqual([{type: 'conversation_list', conversations: [expect.objectContaining({
      sessionId: client.frames[0].sessionId, entryCount: 1,
    })]}]);
    expect(client.frames.some(frame => frame.type === 'stream_end')).toBe(false);
  } finally {
    release();
    await client.until(() => client.frames.some(frame => frame.type === 'stream_end'));
  }
  expect(client.frames.filter(frame => frame.type === 'conversation_list')).toHaveLength(1);
});
